89	diff --git a/lib/features/capture/data/datasources/media_remote_data_source.dart b/lib/features/capture/data/datasources/media_remote_data_source.dart
90	new file mode 100644
91	index 0000000..0c93bbd
92	--- /dev/null
93	+++ b/lib/features/capture/data/datasources/media_remote_data_source.dart
94	@@ -0,0 +1,45 @@
95	+import 'dart:convert';
96	+import 'dart:typed_data';
97	+
98	+import 'package:fpdart/fpdart.dart';
99	+
100	+import '../../../../core/failure/failure.dart';
101	+import '../../../../core/network/api_client.dart';
102	+import '../../domain/repositories/media_repository.dart';
103	+
104	+/// Capture's one OCR call (`media-ocr`) — posts via the shared
105	+/// `ApiClient`, mirroring `entries_remote_data_source.dart`'s pattern.
106	+/// Base64-encodes the image bytes here, and only here (Boundaries) — no
107	+/// other layer ever handles the raw bytes in that encoded form.
108	+class MediaRemoteDataSource {
109	+  MediaRemoteDataSource(this._apiClient);
110	+
111	+  final ApiClient _apiClient;
112	+
113	+  Future<Either<Failure, OcrResult>> recognizeText({
114	+    required Uint8List imageBytes,
115	+    required String mimeType,
116	+  }) async {
117	+    final result = await _apiClient.post(
118	+      'media-ocr',
119	+      data: {'image': base64Encode(imageBytes), 'mimeType': mimeType},
120	+    );
121	+    return result.flatMap((json) {
122	+      try {
123	+        final data = json['data'] as Map<String, dynamic>;
124	+        return right(
125	+          OcrResult(
126	+            text: data['text'] as String,
127	+            confidence: data['confidence'] as String,
128	+          ),
129	+        );
130	+      } catch (error) {
131	+        // A 200 response that doesn't match the expected shape is a
132	+        // client-side parse failure, never a backend-sent code — maps to
133	+        // the local-only `malformedResponse` (RNF09: no exception escapes
134	+        // unmapped).
135	+        return left(Failure.malformedResponse(message: error.toString()));
136	+      }
137	+    });
138	+  }
139	+}
