891	+        unawaited(_deletePickedFile(path));
892	+        emit(const PhotoSaved());
893	+      },
894	+    );
895	+  }
896	+
897	+  /// Called when the Foto tab loses focus mid-pick/mid-OCR
898	+  /// (`InsertionModal`'s tab-switch listener) — I/O matrix's "Leave tab
899	+  /// mid-pick/OCR" row: the in-flight picker/OCR call is discarded, no
900	+  /// `create()` ever fires. A no-op for every other state when
901	+  /// [discardPreserved] is `false` (the default) — in particular
902	+  /// [PhotoRecognized]/[PhotoError], where the Never clause's trivial
903	+  /// scope (resource safety only, not full Story 3.4 cancel-safety)
904	+  /// means a tab switch must preserve the result rather than discard it
905	+  /// — mirrors `AudioEntryCubit.cancel()`'s own `discardPreserved`
906	+  /// convention exactly.
907	+  ///
908	+  /// [discardPreserved] — `InsertionModal.show()`'s `finally` also calls
909	+  /// this (before `close()`) when the *whole modal* is dismissed (✕/
910	+  /// swipe-down/barrier tap), not just the tab. In that case there's no
911	+  /// "switch back to the tab later" to preserve for — the cubit is about
912	+  /// to be closed — so a preserved [PhotoRecognized]/[PhotoError]'s
913	+  /// picked-photo temp file would otherwise never be cleaned up and leak
914	+  /// on disk forever (Review finding — the comment this replaced
915	+  /// incorrectly claimed Foto "never creates a temp file of its own";
916	+  /// `image_picker` does, every pick). Pass `true` only from that call
917	+  /// site.
918	+  Future<void> cancel({bool discardPreserved = false}) async {
919	+    // Bumped unconditionally — including when the state below doesn't
920	+    // match — so an in-flight `_pick`/`_recognize`/`retry` continuation
921	+    // still sees the mismatch and aborts itself even while still awaiting
922	+    // (Review-finding rationale mirrored from `AudioEntryCubit.cancel()`).
923	+    _generation++;
924	+    // Review finding: without this, leaving the Foto tab while the
925	+    // native picker call itself (not yet `PhotoProcessing`) was still in
926	+    // flight left `_picking` stuck `true` forever — the `_generation`
927	+    // bump above already makes that stale continuation a no-op, so
928	+    // resetting this eagerly is always safe.
929	+    _picking = false;
930	+    final current = state;
931	+    if (current is PhotoProcessing) {
932	+      unawaited(_deletePickedFile(current.path));
933	+      emit(const PhotoIdle());
934	+    } else if (discardPreserved) {
935	+      final path = switch (current) {
936	+        PhotoRecognized(path: final p) => p,
937	+        PhotoError(path: final p) => p,
938	+        _ => null,
939	+      };
940	+      if (path != null) {
941	+        unawaited(_deletePickedFile(path));
942	+      }
943	+    }
944	+  }
945	+
946	+  /// Best-effort cleanup for a picked-photo temp file this cubit is done
947	+  /// with (saved successfully, abandoned for good by [cancel], or
948	+  /// replaced by a fresh pick in [_pick]) — deletion failures are
949	+  /// swallowed since nothing in the UI depends on this succeeding,
950	+  /// mirroring `AudioEntryCubit._deleteRecordingFile()`.
951	+  Future<void> _deletePickedFile(String path) async {
952	+    try {
953	+      await File(path).delete();
954	+    } catch (_) {
955	+      // Best-effort — a missing/already-deleted file, or a transient
956	+      // disk error, is never worth surfacing to the user.
957	+    }
958	+  }
959	+}
